export function createGithubResponse(payload: unknown) {
    return {
        json: async () => payload,
        ok: true,
        status: 200,
    } as Response
}

export function createGithubRawResponse(content: string) {
    return {
        ok: true,
        status: 200,
        text: async () => content,
    } as Response
}

export function createGithubStatusResponse(status: number) {
    return {
        json: async () => ({}),
        ok: status >= 200 && status < 300,
        status,
    } as Response
}

export function conversation(path = 'design/activity/card__root-card.json#conversation=agent-1'): AgentConversation {
    return {
        cardInternalId: 'root-card',
        cardPath: 'design/F-1-root.md',
        completedAt: '2026-01-01T00:01:00.000Z',
        entries: [{ content: 'done', id: 'm1', kind: 'message', role: 'assistant', timestamp: '2026-01-01T00:01:00.000Z' }],
        hasExplicitTitle: true,
        id: 'agent-1',
        path,
        providerSessions: [],
        startedAt: '2026-01-01T00:00:00.000Z',
        status: 'completed',
        title: 'Agent run',
        viewed: true,
    }
}

export function activeCardFile(id: string, options: { after?: string; sha?: string; status?: string } = {}): MarkdownFile {
    const content = [
        '---',
        `id: ${id.toUpperCase()}`,
        `internalId: ${id}`,
        `title: ${id.toUpperCase()}`,
        `status: ${options.status ?? 'todo'}`,
        ...(options.after ? [`after: ${options.after}`] : []),
        '---',
        '',
        `# ${id.toUpperCase()}`,
    ].join('\n')

    return { content, path: `design/${id.toUpperCase()}-1-${id}.md`, sha: options.sha }
}

export function createDeferred<T>() {
    let resolveDeferred: (value: T) => void = () => undefined
    let rejectDeferred: (reason?: unknown) => void = () => undefined
    const promise = new Promise<T>((resolve, reject) => {
        resolveDeferred = resolve
        rejectDeferred = reject
    })

    return { promise, reject: rejectDeferred, resolve: resolveDeferred }
}

export function waitForWorkerTurn() {
    return new Promise((resolve) => {
        window.setTimeout(resolve, 0)
    })
}

